.libPaths(c('work/Rlib',.libPaths()));source('work/scripts/mr_methods.R');out<-'outputs/final_analysis';res<-read.csv(file.path(out,'mr_results_corrected.csv'));z<-res[res$method=='IVW random effects',];loo<-read.csv(file.path(out,'mr_leave_one_out.csv'))
for(g in 1:3){ix<-intersect(((g-1)*4+1):(g*4),seq_len(nrow(z)));png(file.path(out,paste0('MR_scatter_panel_',g,'.png')),width=1800,height=if(length(ix)<=2)800 else 1450,res=170);par(mfrow=c(if(length(ix)<=2)1 else 2,2),mar=c(4,4,3,1));for(j in ix){ex<-z$exposure[j];oc<-z$outcome[j];m<-read.csv(file.path(out,paste0('MR_',ex,'_',oc,'_harmonised.csv')));sg<-sign(m$beta_exp);x<-abs(m$beta_exp);y<-m$beta_out*sg;plot(x,y,pch=16,cex=.7,col='#4d7187',xlab=paste(ex,'effect allele-oriented'),ylab=paste(oc,'log odds'),main=paste(ex,'to',oc));abline(0,z$beta[j],col='#a44648',lwd=2);eg<-lm(y~x,weights=1/m$se_out^2);abline(eg,col='#9a873f',lty=2)};dev.off()
 png(file.path(out,paste0('MR_LOO_panel_',g,'.png')),width=1800,height=if(length(ix)<=2)800 else 1450,res=170);par(mfrow=c(if(length(ix)<=2)1 else 2,2),mar=c(4,4,3,1));for(j in ix){ex<-z$exposure[j];oc<-z$outcome[j];m<-loo[loo$exposure==ex&loo$outcome==oc,];plot(seq_len(nrow(m)),m$OR,pch=16,cex=.5,col='#4d7187',ylim=range(c(m$lower,m$upper)),xlab='Index of omitted SNP',ylab='IVW OR',main=paste(ex,'to',oc));segments(seq_len(nrow(m)),m$lower,seq_len(nrow(m)),m$upper,col='#9cb0bc');abline(h=z$OR[j],col='#a44648',lwd=2);abline(h=1,lty=2,col='gray50')};dev.off()
}
